create policy "site photos public read" on storage.objects for select to anon, authenticated using (bucket_id = 'site-photos');
create policy "site photos admin insert" on storage.objects for insert to authenticated with check (bucket_id = 'site-photos' and public.has_role(auth.uid(), 'admin'));
create policy "site photos admin update" on storage.objects for update to authenticated using (bucket_id = 'site-photos' and public.has_role(auth.uid(), 'admin')) with check (bucket_id = 'site-photos' and public.has_role(auth.uid(), 'admin'));
create policy "site photos admin delete" on storage.objects for delete to authenticated using (bucket_id = 'site-photos' and public.has_role(auth.uid(), 'admin'));